// static
bool StructTraits<::crosapi::mojom::SamlUserSessionProperties::DataView, ::crosapi::mojom::SamlUserSessionPropertiesPtr>::Read(
    ::crosapi::mojom::SamlUserSessionProperties::DataView input,
    ::crosapi::mojom::SamlUserSessionPropertiesPtr* output) {
  bool success = true;
  ::crosapi::mojom::SamlUserSessionPropertiesPtr result(::crosapi::mojom::SamlUserSessionProperties::New());
  
      if (success && !input.ReadEmail(&result->email))
        success = false;
      if (success && !input.ReadGaiaId(&result->gaia_id))
        success = false;
      if (success && !input.ReadPassword(&result->password))
        success = false;
      if (success && !input.ReadOauthCode(&result->oauth_code))
        success = false;
  *output = std::move(result);
  return success;
}

